import { useState } from 'react';

export default function AdminScreen({ events, people, onCreateEvent, onDeleteEvent, onDeletePerson }) {
  const [event, setEvent] = useState({ title: '', description: '', date: '', location: '', capacity: 50 });
  async function submit(eventObject) { eventObject.preventDefault(); await onCreateEvent({ ...event, date: new Date(event.date).toISOString(), capacity: Number(event.capacity) }); setEvent({ title: '', description: '', date: '', location: '', capacity: 50 }); }
  return <><div className="screen-heading"><div><span className="section-kicker">CONTROL ROOM</span><h2>Admin console</h2><p>Manage published events and community profiles.</p></div><span className="admin-badge">{people.length} PEOPLE · {events.length} EVENTS</span></div><div className="admin-layout"><form className="admin-form" onSubmit={submit}><h3>Create an event</h3><label>Title<input required value={event.title} onChange={(e) => setEvent({ ...event, title: e.target.value })} /></label><label>Description<textarea required value={event.description} onChange={(e) => setEvent({ ...event, description: e.target.value })} /></label><label>Date and time<input required type="datetime-local" value={event.date} onChange={(e) => setEvent({ ...event, date: e.target.value })} /></label><label>Location<input required value={event.location} onChange={(e) => setEvent({ ...event, location: e.target.value })} /></label><label>Capacity<input required type="number" min="1" value={event.capacity} onChange={(e) => setEvent({ ...event, capacity: e.target.value })} /></label><button className="primary-button">Publish event ↗</button></form><div><div className="admin-events"><h3>Published events</h3>{events.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.title}</strong><small>{item.location}</small></span><button className="danger-icon" onClick={() => onDeleteEvent(item.id)} aria-label={`Delete ${item.title}`}>×</button></div>)}</div><div className="admin-events admin-people"><h3>People directory</h3>{people.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.name}</strong><small>Class of {item.batch_year || '—'} · {item.current_company || 'No company'}</small></span><button className="danger-icon" onClick={() => onDeletePerson(item.user_id || item.id)} aria-label={`Remove ${item.name}`}>×</button></div>)}</div></div></div></>;
}
